<?php if(\App\Executives\AppointmentService::ready()): $executiveRoles=\App\Executives\AppointmentService::memberAppointments((int)$voter['membership_id']); ?>
<section class="card member-panel mb-4" id="member-executive"><div class="card-header"><h2 class="card-title">Executive appointments</h2><?php if($canManage&&$voter['membership_status']==='active'&&empty($voter['is_deceased'])): ?><a class="no-print" href="<?= e(url('executive_appointment_add',['member_id'=>$voter['membership_id']])) ?>">Appoint to office <i class="bi bi-arrow-up-right" aria-hidden="true"></i></a><?php endif; ?></div><div class="card-body">
<?php if(!$executiveRoles): ?><p class="text-secondary mb-0">No current or scheduled executive appointments.</p><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Position</th><th>Jurisdiction</th><th>Service</th></tr></thead><tbody><?php foreach($executiveRoles as $role): ?><tr><td><a href="<?= e(url('executive_appointment',['id'=>$role['id']])) ?>"><?= e($role['position_name_snapshot']) ?></a><small class="table-detail fw-semibold"><?= e(\App\Executives\OrganizationService::label($role)) ?></small><small class="table-detail"><?= e(\App\Executives\AppointmentService::TYPES[$role['appointment_type']]) ?></small></td><td><?= e(\App\Executives\PositionService::LEVELS[$role['organization_level']]) ?><small class="table-detail"><?= e($role['jurisdiction_snapshot']) ?></small></td><td><span class="badge <?= $role['starts_on']>gmdate('Y-m-d')?'bg-info text-dark':'bg-success' ?>"><?= $role['starts_on']>gmdate('Y-m-d')?'Scheduled':'Current' ?></span><small class="table-detail">From <?= e(date_display($role['starts_on'])) ?><?php if($role['expected_ends_on']): ?> · Expected end <?= e(date_display($role['expected_ends_on'])) ?><?php endif; ?></small><?php if($canManage): ?><a class="d-block small mt-2 no-print" href="<?= e(url('executive_appointment_manage',['id'=>$role['id']])) ?>">Manage service</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section>
<?php endif; ?>
